window.POETRY_REGISTER("v5-strict-10-9-0-8718d2080142.js",{"poems":[[38754,2],[52310,2],[57597,2],[93704,7],[96418,7],[106818,7],[114135,7],[118551,7],[121646,7],[136038,7],[140225,7],[142183,7],[146920,7],[151009,7],[158002,7],[192128,7],[200774,7],[210019,7],[211991,7],[218237,7],[218644,7],[219135,7],[219405,7],[221364,7],[221515,7],[223625,7],[224366,7],[225264,7],[229181,7],[236005,7],[236780,7],[246452,7],[266364,7],[267750,7],[271110,7],[272012,7],[272023,7],[273195,7],[287934,7],[287950,7],[287952,7],[293220,7],[293619,7],[295823,7],[299352,7],[301601,7],[303027,7],[303104,7],[310702,7],[312401,7],[313677,7],[314238,7],[317146,7],[321250,7],[347217,9],[347959,9],[354363,9],[359690,9],[359693,9],[364333,9],[365646,9],[366851,9],[368393,10],[379563,10],[391320,13],[395317,13],[411873,8],[414270,8],[425771,8],[432860,8],[434068,8],[436937,8],[458109,8],[472649,8],[472650,8],[486353,8],[491995,8],[492741,8],[502476,8],[506011,8],[509931,8],[521928,8],[524925,8],[539096,8],[550575,8],[551956,8],[552516,8],[553578,8],[554184,8],[554282,8],[556446,8],[557825,8],[564128,8],[566064,8],[566104,8],[575728,8],[576466,8],[584934,8],[648443,16],[648687,16],[650074,5],[663201,5],[671605,5],[705313,5],[708849,5],[709022,5],[714303,5],[714517,5],[739685,20]],"pairs":[["则秦皇不肯敛手下沙丘","孟贲不合低头入蒿里",0],["上天垂光兮熙予以青春","今日何日兮共此良辰",1],["同诗之八第四句缺二字","前引书作风栗似盐苞",2],["予测孔孟兮尔自解则艰","皂听予言兮释尔而还",3],["仙翁释子亦往往而逢兮","吾尝恶其学幻而言哤",4],["玄猨黄鹄翩翻共悲鸣兮","白云翠霭倏忽而阳阴",5],["君不见封禅之君皆不死","岂以衣冠之葬疑轩皇",6],["中忽忽兮外不知其啸吟","野哉邻妻兮曾谓余淫",7],["劝君莫倚陇笛之悲音些","劝君清歌兮投玉琴些",8],["闵仲叔不以口腹累安邑","我其敢用鲑菜烦嘉禾",9],["流来孔多兮自溢于林间","出始一勺兮下合成川",10],["君不见大贤远抱与俗难","何须酒盘柔指鸣哀弹",11],["君不见狄郎志尚冰玉坚","独闻此老近作佳城篇",12],["君不见博陵马周新丰客","时无贞观老死无人识",13],["君不见渠家父子并辔出","东都于今粉绘写为图",14],["民具瞻兮倾百川以为寿","鸿毋遵陆兮公归锦绣",15],["君不见东州钝汉发半缟","日日醉踏碧鸡三井道",16],["君不见拄天拄地邢君牙","不如诗人穷瞎张太祝",17],["君不见朱门玉食烹万羊","不如农家小甑吴粳香",18],["嗟予不能知止如邴曼容","又不能毕昏如尚子平",19],["君不见中流千金博一壶","不如游山饥时粥一盂",20],["莫言酒不到刘伶坟上土","刘伶在时一醉曾三年",21],["君不见李家谪仙吟掉头","解道峨眉山月半轮秋",22],["又不见苏家老仙冰啄句","更说只恐夜深花睡去",22],["掇袤丈之朔雪以澡德兮","袭万壑之清冰而在躬",23],["耿吾独传中郎之素业兮","岂曰矜萧然林下之风",23],["蹇石湖之恸而莫之释兮","小极而隠几乎书之丛",23],["君不见天街十二绿槐满","独有城东之槐应三台",24],["艺兰之九畹兮蕙茞同芬","河润九里兮其源骏奔",25],["君不见昆冈烈焰燔苍穹","中有一气亘天如白虹",26],["吾尝言封侯万里不直钱","不如洛阳负郭二顷田",27],["设侍以金谷倾城之艳姝","酌以宜城九酝之醪敷",28],["君挟此以生兮不隘以大","胡皎以明兮忽湮以暧",29],["子如不暇恤兮亲宁忍忘","孰夺之去兮不少翺翔",29],["谓为远兮何景物之良是","谓在迩耶将径之何由",30],["君不见萧生堪猛岂不忠","君王疑信相半终不容",31],["啜之以太白东坡两谪僊","尚不负乎此山之泉石",32],["君不见荷锄历山岂非野","后来袗衣鼓琴大风雅",33],["君不见昭阳夜静玉栏边","谁知渔阳万骑横戈鋋",34],["此左氏所以愤干溪之痛","而三叹于祈招之德音",35],["予意其欲毁齿而儿不知","所以为是渐取而渐摇",36],["任你德山临济棒喝交驰","到他面前一点用不著",37],["君不见岩花独步秋叶中","穿天出月莫敢相过从",38],["使与春争妍兮曷保常真","岁寒之知兮宁不谓性",39],["盍置诸左右兮观省昭揭","岁寒之歌兮声声激烈",40],["衲僧不肯向省要处受用","甘自区区于道途之上",41],["此其所以发毫端毗尼藏","而树末世精进幢者也",42],["观世音菩萨将钱买胡餠","放下手却是生铁一块",43],["君不见新甫之柏徂徕松","可栋可楹皆在雪霜后",44],["君不见履常长贫冻至死","絮袄不具有识空悲伤",45],["又不见范叔一寒如此极","绨袍之恋千载犹芬芳",45],["潭州城里起五千间寨屋","道林寺里借一百名夫",46],["临济大师到此咬嚼不破","被黄蘗拄杖再三痛打",47],["若夫拟岘台登临而赋诗","不妨寄我清江纸一疋",48],["屋将焚兮燕呢喃以未已","鼎沸兮虱婆娑其不休",49],["为人处惯向弓弦上结丝","横机时每于险处断桥",50],["又尝笑朝鲜无泪可沾巾","悲歌两语为我异妇人",51],["在师中兮岂造次之可离","忠言不闻兮思君忸怩",52],["君不见李白携月到夜郎","一洗瘴天尽入冰壶里",53],["呜呼尔为汉佐兮为忠臣","千秋万岁兮尔楚无人",54],["尚书有云不逢上帝怒汝","若有常送使者到闽去",55],["君不见古昔闭门僵卧人","高似灞桥驴背偿诗债",56],["场有委粟兮而余之不欲","樊则有棘兮非余之乐",57],["岂无人兮余望余之所思","鸿鹄高飞兮孰知其志",58],["君不见骊山牧竖遗烬酷","不如王孙裸葬良亦足",59],["看了那吴山青似越山青","不如今朝醉了明朝醉",60],["看了那吴山青似越山青","不如今朝醉了明朝醉",61],["独不见张公座上三大户","胡为百万一掷成私骰",62],["安得此云化霖雨洗兵甲","散为玉烛四海皆阳和",63],["若夫拟岘台登临而赋诗","不妨寄我清江纸一疋",64],["君不见李白携月到夜郎","一洗瘴天尽入冰壶里",65],["君不见袁安僵卧寒正骄","王维乃作雪里之芭蕉",66],["九罭寸目兮岂不密且周","惟鲂及鲔兮竭泽是求",67],["归来兮人间不可以久游","烟霞为家兮白云蒙头",68],["又不见鼎湖龙去不复返","独留遗迹千古存苍穹",69],["骎骎吾将捐其袂解其襟","脱苍龙之佩荆玉之簪",70],["胡不与之同时以敷荣兮","而俟彼之色变而叶脱",71],["君不见扶风令死封公卿","嗟尔略阳之令胡为生",72],["君不见吴山高起千万丈","上有烟岚变化出奇状",73],["吾不知使君理郡何如也","父老欲挽不留遥相将",74],["我愿君王目视远烛沕穆","望见山西境上多白骨",75],["我愿君王耳聪听几万里","时闻山西哭声夜不止",75],["吁嗟乎人中之凤乃所珍","我爱南宫上卿美且仁",76],["君不见蓬莱方丈三韩东","上有飞楼涌阁何穹崇",77],["长安冠带隘巷陌而相求","胡为乎逐西风而远去",78],["君不见萱花丛开傍慈竹","忧怀释尽长对猗猗菉",79],["又驱黑海跋浪翻溟吞舟","巨鳅群归尾闾清海灾",80],["上则九峰八峪四崖六岭","其下汶漯济涓流汹汹",81],["君不见天津桥南筑糟丘","何如金陵城西之酒楼",82],["百鸟过之徊翔而不敢下","丹穴之禽经此留遗音",83],["吁嗟天地茫茫安所将之","我已牢骚廓落君胡为",84],["岂不闻当尧之时水逆行","泛滥于天下使禹治之",85],["君不见鱼乱繇来从罟设","杀机今日何人不满腔",86],["曾不知夫蕙华之既落兮","犹窃冀夫芰荷之可衽",87],["一上一回气欲绝而辄止","安得此身直抵摩苍天",88],["君不见黄旌白羽满红皋","谋臣策士争命于波涛",89],["岂曾参伯奇之化其肠兮","而龙逢比干之存其尸",90],["又不则化尔为员丘之竹","若倚骄之礧砢而离离",90],["君不见昏迷天象羲和戮","况也阳曦掩炤归蒙谷",91],["岭南鼻饮有古风榴花香","况乃产乎王生之故乡",92],["覆以千年之松百年之柏","下有青泉昼夜流湱湱",93],["男儿生不逢孔孟在邹鲁","忍使昔圣今贤终寂寞",94],["君莫是攀龙曾上九天飞","学得轩辕数曲之所为",95],["君不闻幻游天地同旅泊","我身安得驾鹤从西东",96],["盖智者不訾予以迷邦兮","而枉者将罪予以怀璧",97],["尧舜圣已没兮孰为忠直","高山崔巍兮水流汤汤",98],["尧舜圣已没兮孰为忠直","高山崔巍兮水流汤汤",99],["有巢氏不肯在山窝里睡","榆林遭殃才滚就了椽",100],["吾闻天台山高万八千丈","中有石室金庭共峛崺",101],["又不知雁门关外荷戈日","可曾持汝悲歌望京邑",102],["吁嗟乎秦皇汉武求神仙","何如此槐此柏能延年",103],["君不见周子定居庐阜时","濂溪风月年年今不古",104],["君不见当年梁惠霸业羞","犹能自移老稚河内粟",105],["尔既无黄鹄翔云之俊翮","又无白鹤乘轩之仙骨",106],["胡为乎袖手独立犹守愚","岂缘年届爱莲惮驰驱",107],["君不见遗子韦侯只一经","相门出相那在金满籯",108],["又不见燕山教子以义方","灵椿老去五枝丹桂芳",108]]});
